input.content:
// Color scheme for sectors
const sectorColors = {
    'Information Technology': '#3498db',
    'Industry': '#e74c3c',
    'Energy': '#27ae60',
    'Financial': '#9b59b6',
    'ETF': '#95a5a6'
};

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return 'N/A';
    const num = parseFloat(value);
    if (num >= 1e12) {
        return (num / 1e12).toFixed(2) + 'T';
    } else if (num >= 1e9) {
        return (num / 1e9).toFixed(2) + 'B';
    } else if (num >= 1e6) {
        return (num / 1e6).toFixed(2) + 'M';
    }
    return num.toLocaleString();
}

// Global state
let selectedTicker = null;
let stockData = [];
let simulation = null;

// Load and process data
async function loadData() {
    const response = await d3.csv('data/stock-descriptions.csv');

    stockData = response.map(d => ({
        ticker: d.ticker,
        name: d['full name'],
        sector: d.sector,
        marketCap: d.marketCap ? parseFloat(d.marketCap) : null,
        country: d.country || null,
        website: d.website || null,
        isETF: d.sector === 'ETF'
    }));

    return stockData;
}

// Create the bubble chart
function createBubbleChart(data) {
    const container = document.getElementById('bubble-chart');
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Clear previous content
    container.innerHTML = '';

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    // Create tooltip
    const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'tooltip')
        .style('opacity', 0)
        .style('display', 'none');

    // Calculate bubble sizes
    const marketCaps = data.filter(d => d.marketCap).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(marketCaps), d3.max(marketCaps)])
        .range([15, 50]);

    const defaultETFRadius = 20;

    // Assign radius to each node
    data.forEach(d => {
        d.radius = d.marketCap ? radiusScale(d.marketCap) : defaultETFRadius;
    });

    // Define sector centers for clustering
    const sectors = [...new Set(data.map(d => d.sector))];
    const sectorCenters = {};
    const numSectors = sectors.length;
    const centerX = width / 2;
    const centerY = height / 2;
    const clusterRadius = Math.min(width, height) * 0.25;

    sectors.forEach((sector, i) => {
        const angle = (i / numSectors) * 2 * Math.PI - Math.PI / 2;
        sectorCenters[sector] = {
            x: centerX + clusterRadius * Math.cos(angle),
            y: centerY + clusterRadius * Math.sin(angle)
        };
    });

    // Create force simulation
    simulation = d3.forceSimulation(data)
        .force('charge', d3.forceManyBody().strength(5))
        .force('center', d3.forceCenter(centerX, centerY))
        .force('collision', d3.forceCollide().radius(d => d.radius + 2).strength(1))
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.3))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.3))
        .on('tick', ticked);

    // Create bubble groups
    const bubbleGroups = svg.selectAll('.bubble-group')
        .data(data)
        .enter()
        .append('g')
        .attr('class', 'bubble-group');

    // Create bubbles
    const bubbles = bubbleGroups.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector])
        .attr('data-ticker', d => d.ticker)
        .on('mouseover', function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style('display', 'block')
                    .style('opacity', 1)
                    .html(`
                        <div class="ticker">${d.ticker}</div>
                        <div class="name">${d.name}</div>
                        <div class="sector">${d.sector}</div>
                    `);
            }
        })
        .on('mousemove', function(event) {
            tooltip
                .style('left', (event.pageX + 15) + 'px')
                .style('top', (event.pageY - 10) + 'px');
        })
        .on('mouseout', function() {
            tooltip
                .style('opacity', 0)
                .style('display', 'none');
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Create labels
    const labels = bubbleGroups.append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius * 0.5, 12) + 'px');

    function ticked() {
        bubbleGroups.attr('transform', d => {
            // Keep bubbles within bounds
            d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
            d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
            return `translate(${d.x}, ${d.y})`;
        });
    }

    // Create legend
    createLegend(sectors);
}

// Create legend for sectors
function createLegend(sectors) {
    const legendContainer = document.getElementById('legend');
    legendContainer.innerHTML = '';

    sectors.forEach(sector => {
        const item = document.createElement('div');
        item.className = 'legend-item';

        const colorBox = document.createElement('div');
        colorBox.className = 'legend-color';
        colorBox.style.backgroundColor = sectorColors[sector];

        const label = document.createElement('span');
        label.textContent = sector;

        item.appendChild(colorBox);
        item.appendChild(label);
        legendContainer.appendChild(item);
    });
}

// Create the data table
function createDataTable(data) {
    const tbody = document.querySelector('#stock-table tbody');
    tbody.innerHTML = '';

    data.forEach(d => {
        const row = document.createElement('tr');
        row.setAttribute('data-ticker', d.ticker);
        row.onclick = () => selectStock(d.ticker);

        row.innerHTML = `
            <td>${d.ticker}</td>
            <td>${d.name}</td>
            <td>${d.sector}</td>
            <td>${formatMarketCap(d.marketCap)}</td>
        `;

        tbody.appendChild(row);
    });
}

// Select a stock (highlight in both chart and table)
function selectStock(ticker) {
    // Clear previous selection
    d3.selectAll('.bubble').classed('selected', false);
    document.querySelectorAll('#stock-table tbody tr').forEach(row => {
        row.classList.remove('selected');
    });

    if (selectedTicker === ticker) {
        selectedTicker = null;
        return;
    }

    selectedTicker = ticker;

    // Highlight bubble
    d3.selectAll('.bubble')
        .filter(d => d.ticker === ticker)
        .classed('selected', true);

    // Highlight and scroll to table row
    const tableRow = document.querySelector(`#stock-table tbody tr[data-ticker="${ticker}"]`);
    if (tableRow) {
        tableRow.classList.add('selected');
        tableRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}

// Initialize the visualization
async function init() {
    try {
        const data = await loadData();
        createBubbleChart(data);
        createDataTable(data);

        // Handle window resize
        window.addEventListener('resize', () => {
            if (simulation) {
                simulation.stop();
            }
            createBubbleChart(data);
        });
    } catch (error) {
        console.error('Error loading data:', error);
    }
}

// Start the app
document.addEventListener('DOMContentLoaded', init);

